function initAudio(){if(!audio){audio=new(window.AudioContext||window.webkitAudioContext)();const buffer=audio.createBuffer(1,audio.sampleRate*4,audio.sampleRate),data=buffer.getChannelData(0);let old=0;for(let i=0;i<data.length;i++){old=(old+Math.random()*.02-.01)*.99;data[i]=old;}const source=audio.createBufferSource();source.buffer=buffer;source.loop=true;const filter=audio.createBiquadFilter();filter.type='lowpass';filter.frequency.value=1300;ambient=audio.createGain();ambient.gain.value=.4;source.connect(filter).connect(ambient).connect(audio.destination);source.start();}if(audioOn)audio.resume();else audio.suspend();}
function sound(kind='wood'){if(!audioOn||!started)return;initAudio();const duration={wood:.12,paper:.22,metal:.45,cloth:.4,unlock:.75,ring:.8}[kind]||.15;const g=audio.createGain();g.gain.setValueAtTime(.001,audio.currentTime);g.gain.linearRampToValueAtTime(kind==='ring'?.06:.12,audio.currentTime+.012);g.gain.exponentialRampToValueAtTime(.0001,audio.currentTime+duration);g.connect(audio.destination);
 if(['metal','unlock','ring'].includes(kind)){for(const f of kind==='ring'?[620,840]:kind==='unlock'?[135,230,380]:[390,720]){const o=audio.createOscillator();o.type='sine';o.frequency.setValueAtTime(f,audio.currentTime);o.frequency.exponentialRampToValueAtTime(f*.82,audio.currentTime+duration);o.connect(g);o.start();o.stop(audio.currentTime+duration);}}else{const b=audio.createBuffer(1,Math.ceil(audio.sampleRate*duration),audio.sampleRate),d=b.getChannelData(0);let old=0;for(let i=0;i<d.length;i++){old=.65*old+Math.random()*.7-.35;d[i]=old;}const s=audio.createBufferSource();s.buffer=b;const f=audio.createBiquadFilter();f.type='lowpass';f.frequency.value=kind==='paper'?2600:kind==='cloth'?900:360;s.connect(f).connect(g);s.start();}}
