const luggageDigits=[0,0,0],safeSymbols=[0,0,0,0];
function openLuggage(){
 room.setPuzzleDials(luggageDigits,safeSymbols);
 if(state.luggageOpen){modal('<h2>열린 여행가방</h2><p>안감에는 오르골을 눌러 놓았던 자국이 있다. 작은 태엽 열쇠는 이미 챙겼다.</p>');return;}
 modal(`<h2>여행가방의 세 자리 잠금</h2><p>손잡이에는 수하물표를 매달았던 끈이 남아 있다.<br>세 숫자 고리는 서로 따로 돌아간다.</p><div class="guest-dials">${luggageDigits.map((v,i)=>`<div><button class="outline" data-luggage="${i}" data-delta="1" aria-label="여행가방 ${i+1}번째 숫자 올리기">+</button><output id="luggageDigit${i}">${v}</output><button class="outline" data-luggage="${i}" data-delta="-1" aria-label="여행가방 ${i+1}번째 숫자 내리기">−</button></div>`).join('')}</div><button class="primary" id="openLuggage">가방 잠금쇠 당기기 <span>→</span></button><p id="luggageFeedback" role="status"></p>`);
 document.querySelectorAll('[data-luggage]').forEach(b=>b.onclick=()=>{const i=+b.dataset.luggage;luggageDigits[i]=(luggageDigits[i]+ +b.dataset.delta+10)%10;$('#luggageDigit'+i).textContent=luggageDigits[i];room.setPuzzleDials(luggageDigits,safeSymbols);sound('metal');});
 $('#openLuggage').onclick=()=>{if(unlockLuggage(state,luggageDigits.join(''))){closeModal();inventory();sound('unlock');record('317호 여행가방','잠금이 풀린 여행가방 안에서 작은 오르골 태엽 열쇠를 얻었다.');caption('옷 사이에 작은 태엽 열쇠가 숨어 있었다.');}else{$('#luggageFeedback').textContent='잠금쇠가 걸린다. 숫자의 순서를 다시 살펴보자.';sound('wood');}};
}
function openMusicBox(){
 if(!state.musicWound){modal('<h2>멈춰 있는 오르골</h2><p>뚜껑 안에는 네 개의 작은 문양판.<br>옆면의 태엽 구멍이 비어 있어 움직이지 않는다.</p><p class="muted">맞는 물건을 I 인벤토리에서 손에 든 뒤 오르골에 사용해 보세요.</p>');return;}
 modal('<h2>317호의 야상곡</h2><p>태엽이 감겼다. 연주 중에는 문양판이 하나씩 뒤집힌다.<br>소리를 꺼도 문양과 순서를 볼 수 있어요.</p><div class="music-stage" id="musicStage" role="status" aria-live="polite">재생을 기다리는 네 개의 문양판</div><button class="primary" id="playMusic">오르골 재생 <span>→</span></button><p class="muted">필요하면 여러 번 재생할 수 있습니다.</p>','music');
 const stage=$('#musicStage'),button=$('#playMusic');button.onclick=()=>{
   button.disabled=true;stage.replaceChildren();let n=0;
   const next=()=>{if(modalKind!=='music'||$('#modal').hidden||$('#musicStage')!==stage)return;
     if(n===MUSIC_SEQUENCE.length){hearTune(state);record('317호 오르골','문양판이 달 → 종 → 물결 → 별 순서로 뒤집혔다. 옷장 아래 금고에도 같은 문양이 있다.');button.disabled=false;button.textContent='다시 재생';return;}
     const i=MUSIC_SEQUENCE[n],piece=document.createElement('span');piece.innerHTML=`${symbolSVG(i)}<b>${n+1}. ${SYMBOLS[i].name}</b>`;stage.append(piece);musicNote(i);n++;setTimeout(next,1050);
   };next();
 };
}
function musicNote(i){if(!audioOn)return;initAudio();const o=audio.createOscillator(),g=audio.createGain();o.type='sine';o.frequency.value=[523.25,440,659.25,587.33][i];g.gain.setValueAtTime(.0001,audio.currentTime);g.gain.linearRampToValueAtTime(.14,audio.currentTime+.015);g.gain.exponentialRampToValueAtTime(.0001,audio.currentTime+.9);o.connect(g).connect(audio.destination);o.start();o.stop(audio.currentTime+1);}
function openSafe(){
 room.setPuzzleDials(luggageDigits,safeSymbols);
 if(state.safeOpen){modal('<h2>열린 객실 금고</h2><p>안쪽 방 열쇠는 이미 챙겼다. 남은 봉투에는 “우리는 같은 밤에 이곳에 있었다”라고 적혀 있다.</p>');return;}
 modal(`<h2>네 문양의 객실 금고</h2><p>손잡이 위에 네 개의 문양판이 줄지어 있다.<br>누르면 다음 문양으로 돌아간다.</p><div class="safe-symbols">${safeSymbols.map((v,i)=>`<button class="outline" data-safe="${i}" aria-label="금고 ${i+1}번째 문양 바꾸기">${symbolSVG(v)}<span>${SYMBOLS[v].name}</span></button>`).join('')}</div><button class="primary" id="openSafe">금고 손잡이 당기기 <span>→</span></button><p id="safeFeedback" role="status"></p>`);
 document.querySelectorAll('[data-safe]').forEach(b=>b.onclick=()=>{const i=+b.dataset.safe;safeSymbols[i]=(safeSymbols[i]+1)%4;room.setPuzzleDials(luggageDigits,safeSymbols);b.innerHTML=symbolSVG(safeSymbols[i])+`<span>${SYMBOLS[safeSymbols[i]].name}</span>`;sound('metal');});
 $('#openSafe').onclick=()=>{if(unlockSafe(state,safeSymbols)){closeModal();inventory();sound('unlock');record('317호 안쪽 방 열쇠','오르골 문양 순서로 금고를 열었다. 317 INNER 열쇠와 “우리는 같은 밤에 이곳에 있었다”라는 메모.');caption('금고에서 317호 안쪽 방 열쇠를 얻었다.');}else{$('#safeFeedback').textContent=state.tuneHeard?'손잡이는 돌아가지 않는다. 문양의 순서가 다른 것 같다.':'문양의 순서를 확인할 단서가 필요하다. 방 안의 같은 문양을 찾아보자.';sound('wood');}};
}

function journal(){modal(`<div class="overline">THINGS YOU HAVE NOTICED</div><h2>관찰 기록</h2>${state.notes.length?state.notes.map(n=>`<div class="journal-entry"><b>${escape(n.title)}</b><p>${escape(n.text)}</p></div>`).join(''):'<p>아직 적어 둔 것이 없다.<br>사물의 흔적과 읽은 내용은 이곳에 남는다.</p>'}<p class="muted">기록은 발견한 사실만 남깁니다. 다음에 할 일이나 정답을 자동으로 알려주지 않습니다.</p>`);}
function bag(){
 inventoryOpened=true;inventoryUnread=false;inventory();
 modal(`<h2>인벤토리 <kbd>I</kbd></h2><p class="inventory-intro">가진 물건을 다시 조사해 단서를 찾고, 방 안의 대상에 사용할 수 있어요.</p>
 <ul class="inventory-instructions"><li><strong>조사해서 단서 찾기</strong><span>물건을 뒤집고 확대해 글씨·뒷면·표면의 흔적을 살펴보세요.</span></li><li><strong>물건 사용하기</strong><span>‘손에 들기’를 누른 뒤, 사용할 대상 앞에서 <kbd>E</kbd>를 누르세요.</span></li><li><strong>물건 조합하기</strong><span>조합할 수 있는 물건을 모으면 조합 버튼이 나타나요.</span></li></ul>
 <div class="inventory-item-list">${state.inventory.map(id=>`<article class="inventory-entry"><strong>${ITEMS[id]}</strong><div class="inventory-item-actions"><button class="outline" data-inspect="${id}" aria-label="${ITEMS[id]} 조사하기">조사하기</button>${CLUE_ONLY.has(id)?'':state.selected===id?`<button class="outline" data-unequip="${id}" aria-label="${ITEMS[id]} 선택 해제">선택 해제</button>`:`<button class="outline" data-equip="${id}" aria-label="${ITEMS[id]} 손에 들기">손에 들기</button>`}</div></article>`).join('')}</div>
 ${!state.inventory.length?'<p class="inventory-empty"><strong>아직 가진 물건이 없어요.</strong><span>방에서 물건을 얻으면 여기에 모입니다.</span></p>':''}
 <div class="buttonrow">${state.inventory.includes('filmA')&&state.inventory.includes('filmB')?'<button class="outline" id="joinFilms">두 필름 조각 합치기</button>':''}</div><p class="inventory-shortcut"><kbd>I</kbd> 또는 <kbd>ESC</kbd>로 닫기</p>`,'inventory');
 document.querySelectorAll('[data-inspect]').forEach(b=>b.onclick=()=>{const id=b.dataset.inspect;closeModal();inspectItem(id);});
 document.querySelectorAll('[data-equip]').forEach(b=>b.onclick=()=>equipItem(b.dataset.equip));
 document.querySelectorAll('[data-unequip]').forEach(b=>b.onclick=()=>{state.selected=null;closeModal();inventory();toast('물건 선택을 해제했습니다.');});
 if($('#joinFilms'))$('#joinFilms').onclick=()=>{combineFilms(state);record('이어진 필름','찢긴 두 조각이 서로 맞물렸다.');inventory();closeModal();inspectItem('film');};
}
function hint(){const p=phase(state);if(p!==hintPhase){hintPhase=p;hintStep=0;}modal(`<div class="overline">A SMALL NUDGE</div><h2>잠깐, 다른 시선으로.</h2><p>도움은 한 번에 한 단계씩 보여줍니다.<br>마지막 단계는 구체적인 해결 방법을 포함합니다.</p><div class="note" id="hintText">아직 도움을 요청하지 않았습니다.</div><button class="outline" id="nextHint" style="margin-top:20px">첫 번째 도움 보기</button>`);$('#nextHint').onclick=()=>{const lines=HINTS[p];$('#hintText').textContent=lines[Math.min(hintStep,2)];if(hintStep<3){hintStep++;state.hints++;}$('#nextHint').textContent=hintStep<3?`더 구체적으로 보기 (${hintStep}/3)`:'모든 도움을 확인했습니다';$('#nextHint').disabled=hintStep>=3;};}
function help(){modal('<div class="overline">HOW TO LOOK CLOSER</div><h2>눈높이를 바꿔보세요.</h2><p>PC 키보드와 마우스로 플레이합니다.</p><p>316호는 두 침실·거실·간이주방·욕실로 나뉜 스위트룸입니다. 거실 출입문을 나서면 호텔 복도가 나오고, 복도에서 317호로 들어갈 수 있습니다.</p><div class="note">WASD — 걷기<br>마우스 드래그 / 방향키 — 시점<br>화면 클릭 — 마우스 시점 잠금<br>E 또는 물건 클릭 — 조사<br>C — 몸 낮추기 / 일어서기<br>I — 인벤토리 열기/닫기 · J — 관찰 기록 · H — 선택형 도움<br>1–5 — 소지품 선택 · ESC — 닫기 / 일시정지</div><p>물건을 들여다볼 때는 드래그로 뒤집고 휠로 확대합니다.<br>인벤토리에서 물건을 선택한 뒤, 대상 앞에서 E로 사용할 수 있습니다.</p><p class="muted">다음 행동은 자동 안내하지 않습니다. 정답은 여러 발견을 연결해야 알 수 있습니다.</p>');}
function start(explore){state.explore=explore;state.doorOpen=explore;state.room317Open=explore;state.exitOpen=explore;state.stairsOpen=explore;for(const k of ['bedroomOpen','kitchenOpen','twinOpen','bathUnlocked','bathDoorOpen'])state[k]=explore;started=true;complete=false;paused=false;$('#landing').hidden=true;$('#hud').hidden=false;$('#modeName').textContent=explore?'자유 탐색 · L 조명 / U 스탠드':'관찰은 당신의 몫이다.';player.set(0,1.62,2.7);yaw=0;pitch=-.015;initAudio();inventory();record('316호 스위트룸에서 깨어나다','침실 옆에는 욕실, 안쪽 문 너머에는 거실과 간이주방, 동행인의 트윈 침실이 있다. 호텔 복도로 나가는 출입문은 거실에 있다.');caption(explore?'열린 방을 자유롭게 둘러볼 수 있습니다.':'316호의 침실에서 눈을 떴다.\n거실로 이어지는 안쪽 문이 잠겨 있다.',6200);}
function finish(){if(complete)return;if(state.explore)return;if(!state.exitOpen||!state.safeOpen)return;complete=true;state.complete=true;releaseMouse();$('#caption').classList.remove('show');$('#toast').classList.remove('show');$('#hud').hidden=true;$('#ending').hidden=false;const t=Math.round(state.seconds);$('#result').textContent=`조사 시간 ${Math.floor(t/60)}분 ${t%60}초  /  관찰 기록 ${state.notes.length}개  /  도움 ${state.hints}회`;sound('unlock');}
const adminEnabled=new URLSearchParams(location.search).get('admin')==='1';
let adminPointId='bedroom',adminFree=false,adminAutoResume=true;
function storageRead(key){try{return localStorage.getItem(key);}catch{return null;}}
function storageWrite(key,value){try{localStorage.setItem(key,value);return true;}catch{return false;}}
function adminSettings(){storageWrite(SETTINGS_KEY,JSON.stringify({pointId:adminPointId,free:adminFree,autoResume:adminAutoResume}));}
function currentCheckpoint(){return writeCheckpoint({state,pointId:adminPointId,position:player.toArray(),yaw,pitch,clockHour,clockMinute,luggageDigits,safeSymbols});}
function saveAdminPoint(quiet=false){if(!adminEnabled||!started||complete)return false;const ok=storageWrite(CHECKPOINT_KEY,currentCheckpoint());if(!quiet)toast(ok?'현재 테스트 지점을 저장했습니다.':'브라우저 저장소를 사용할 수 없어 이번 지점을 저장하지 못했습니다.');return ok;}
function applyAdminState(snapshot){
 closeInspection();releaseMouse();closeModal();
 for(const key of Object.keys(state))delete state[key];Object.assign(state,snapshot.state);state.complete=false;
 started=true;complete=false;paused=false;mode='walk';active=null;crouched=false;drag=false;moved=false;
 luggageDigits.splice(0,3,...(snapshot.luggageDigits||(snapshot.state.luggageOpen?[2,8,4]:[0,0,0])));safeSymbols.splice(0,4,...(snapshot.safeSymbols||(snapshot.state.safeOpen?MUSIC_SEQUENCE:[0,0,0,0])));
 room.setPuzzleDials(luggageDigits,safeSymbols);
 clockHour=snapshot.clockHour;clockMinute=snapshot.clockMinute;room.clockHands(clockHour,clockMinute);room.update(1,elapsed);
 const point=getTestStart(snapshot.pointId);adminPointId=point.id;let position=snapshot.position;
 if(!room.canMove(position[0],position[2])){const zone=zoneAt(position[0],position[2]);const fallback=getTestStart(zone==='exitHall'?'exit':zone==='lowerHall'?'downstairs':zone||point.id);position=fallback.position;if(!room.canMove(position[0],position[2]))position=point.position;}
 player.fromArray(position);player.y=1.62;yaw=snapshot.yaw;pitch=snapshot.pitch;
 camera.fov=57;camera.updateProjectionMatrix();camera.position.copy(player);camera.rotation.set(pitch,yaw,0);camera.updateMatrixWorld();room.scene.updateMatrixWorld(true);
 $('#landing').hidden=true;$('#ending').hidden=true;$('#pause').hidden=true;$('#inspection').hidden=true;$('#hud').hidden=false;$('#prompt').hidden=true;
 $('#caption').classList.remove('show');$('#toast').classList.remove('show');$('#modeName').textContent='관리자 테스트 · F2로 위치 변경';
 inventoryOpened=true;inventoryUnread=false;knownInventory.clear();state.inventory.forEach(id=>knownInventory.add(id));inventory();hintPhase='';hintStep=0;phoneTimer=0;
 $('#pause .muted').textContent=adminAutoResume?'관리자 테스트는 위치와 진행을 자동 저장합니다. F2로 시작 위치를 바꿀 수 있습니다.':'관리자 테스트 · F2에서 저장하거나 다른 지점을 선택할 수 있습니다.';
 adminSettings();if(adminAutoResume)saveAdminPoint(true);
}
function startAdminPoint(id,free){
 const setup=createTestStart(id,free),p=setup.point,dx=p.look[0]-p.position[0],dz=p.look[2]-p.position[2];adminFree=free;
 applyAdminState({state:setup.state,pointId:p.id,position:p.position,yaw:Math.atan2(-dx,-dz),pitch:Math.atan2(p.look[1]-p.position[1],Math.hypot(dx,dz)),clockHour:setup.clockHour,clockMinute:setup.clockMinute});
 toast('관리자 테스트 · '+p.label,3500);
}
function adminPanel(){
 if(!adminEnabled||!assetsReady)return;
 const saved=readCheckpoint(storageRead(CHECKPOINT_KEY));
 const groups=[...new Set(TEST_STARTS.map(p=>p.group))];
 modal(`<h2>관리자 테스트</h2><p class="admin-intro">확인할 공간이나 퍼즐 단계에서 바로 시작하세요. 플레이 중에도 <kbd>F2</kbd>로 다시 열 수 있어요.</p>
 <label class="admin-field" for="adminStartPoint"><span>시작 위치 · 진행 단계</span><select id="adminStartPoint">${groups.map(group=>`<optgroup label="${group}">${TEST_STARTS.filter(p=>p.group===group).map(p=>`<option value="${p.id}" ${p.id===adminPointId?'selected':''}>${p.label}</option>`).join('')}</optgroup>`).join('')}</select></label>
 <p id="adminStartDescription" class="admin-description">${getTestStart(adminPointId).description}</p>
 <label class="admin-check"><input id="adminFree" type="checkbox" ${adminFree?'checked':''}><span>모든 문을 열고 자유롭게 둘러보기<small>퍼즐 단계의 소지품은 유지하고, 완료 화면은 표시하지 않습니다.</small></span></label>
 <label class="admin-check"><input id="adminAutoResume" type="checkbox" ${adminAutoResume?'checked':''}><span>패치·새로고침 후 자동으로 이어가기<small>관리자 모드에서 위치와 진행 상태를 이 브라우저에 자동 저장합니다.</small></span></label>
 <button class="primary" id="adminLaunch">선택한 지점에서 시작 <span>→</span></button><p class="admin-reset-note">시작하면 현재 테스트 진행을 선택한 단계로 바꿉니다.</p>
 <div class="admin-checkpoint"><h3>저장 지점</h3><p id="adminSavedDescription">${saved?`${getTestStart(saved.pointId).label} · ${new Date(saved.savedAt).toLocaleString('ko-KR')}`:'아직 저장된 테스트 지점이 없습니다.'}</p>
 <div class="admin-actions"><button class="outline" id="adminSave" ${!started||complete?'disabled':''}>현재 지점 저장</button><button class="outline" id="adminRestore" ${!saved?'disabled':''}>저장 지점 불러오기</button><button class="quiet" id="adminClear" ${!saved?'disabled':''}>저장 지점 지우기</button></div></div>
 <button class="quiet" id="adminNormal">일반 플레이로 돌아가기</button>`,'admin');
 $('#adminStartPoint').onchange=e=>{$('#adminStartDescription').textContent=getTestStart(e.target.value).description;};
 $('#adminLaunch').onclick=()=>{adminAutoResume=$('#adminAutoResume').checked;startAdminPoint($('#adminStartPoint').value,$('#adminFree').checked);};
 $('#adminAutoResume').onchange=e=>{adminAutoResume=e.target.checked;adminSettings();};
 $('#adminSave').onclick=()=>{if(saveAdminPoint()){adminPanel();}};
 $('#adminRestore').onclick=()=>{const checkpoint=readCheckpoint(storageRead(CHECKPOINT_KEY));if(checkpoint){adminFree=checkpoint.state.explore;applyAdminState(checkpoint);toast('저장한 테스트 지점을 불러왔습니다.');}else{adminPanel();toast('저장 지점을 읽을 수 없습니다. 시작 위치를 다시 선택하세요.');}};
 $('#adminClear').onclick=()=>{try{localStorage.removeItem(CHECKPOINT_KEY);}catch{}adminAutoResume=false;adminSettings();adminPanel();};
 $('#adminNormal').onclick=()=>{const url=new URL(location.href);url.searchParams.delete('admin');url.searchParams.delete('start');url.searchParams.delete('free');location.assign(url.href);};
}
if(adminEnabled){
 try{const settings=JSON.parse(storageRead(SETTINGS_KEY));if(settings){adminPointId=getTestStart(settings.pointId).id;adminFree=settings.free===true;adminAutoResume=settings.autoResume!==false;}}catch{}
 $('#adminButton').hidden=false;$('#adminLanding').hidden=false;$('#adminButton').onclick=$('#adminLanding').onclick=adminPanel;
 setInterval(()=>{if(adminAutoResume&&started&&!complete&&!paused&&mode==='walk')saveAdminPoint(true);},2000);
}
function initializeAdmin(){
 if(!adminEnabled)return;$('#adminButton').disabled=false;
 const params=new URLSearchParams(location.search),explicit=params.get('start');
 if(TEST_STARTS.some(p=>p.id===explicit)){startAdminPoint(explicit,params.get('free')==='1');return;}
 const saved=readCheckpoint(storageRead(CHECKPOINT_KEY));if(adminAutoResume&&saved){adminFree=saved.state.explore;applyAdminState(saved);toast('관리자 테스트 · 저장 지점에서 이어갑니다.');}else adminPanel();
}

$('#inventoryButton').onclick=$('#inventoryGuide').onclick=bag;
$('#storyStart').onclick=()=>start(false);$('#exploreStart').onclick=()=>start(true);$('#closeInspect').onclick=closeInspection;$('#closeModal').onclick=closeModal;$('#resume').onclick=resume;$('#restart').onclick=$('#endingRestart').onclick=()=>location.reload();$('#returnRoom').onclick=()=>{complete=false;state.explore=true;$('#ending').hidden=true;$('#hud').hidden=false;$('#modeName').textContent='해결한 밀실 · 자유 탐색';};$('#pauseButton').onclick=pause;$('#journalButton').onclick=journal;$('#hintButton').onclick=hint;$('#help').onclick=help;$('#brand').onclick=e=>{e.preventDefault();pause();};$('#sound').onclick=()=>{audioOn=!audioOn;$('#sound').textContent=audioOn?'SOUND ON':'SOUND OFF';if(audio||started)initAudio();};$('#fullscreen').onclick=()=>{if(document.fullscreenElement)document.exitFullscreen();else document.documentElement.requestFullscreen?.().catch(()=>toast('브라우저 창을 넓혀서 플레이해 주세요.'));};
document.addEventListener('keydown',e=>{if(e.code==='F2'&&adminEnabled){e.preventDefault();if(!$('#modal').hidden&&modalKind==='admin')closeModal();else adminPanel();return;}if(['INPUT','TEXTAREA','SELECT'].includes(e.target.tagName)||e.target.isContentEditable)return;if(e.code==='Escape'){e.preventDefault();if(['inspect','focus'].includes(mode))closeInspection();else if(!$('#modal').hidden)closeModal();else if(!$('#pause').hidden)resume();else pause();return;}if(!started||complete)return;if(e.repeat&&['KeyE','KeyC','KeyI','KeyJ','KeyH'].includes(e.code))return;if(e.code==='KeyI'){e.preventDefault();if(!$('#pause').hidden)return;if(!$('#modal').hidden&&modalKind==='inventory')closeModal();else bag();return;}if(!$('#modal').hidden||!$('#pause').hidden||mode==='inspect')return;if(e.code==='KeyJ'){journal();return;}if(e.code==='KeyH'){hint();return;}if(state.explore&&e.code==='KeyL'){state.lightOn=!state.lightOn;return;}if(state.explore&&e.code==='KeyU'){state.uvInstalled=!state.uvInstalled;state.lampOn=true;return;}if(e.code==='KeyC'){crouched=!crouched;toast(crouched?'몸을 낮췄다.':'몸을 일으켰다.');return;}if(/^Digit[1-5]$/.test(e.code)){const id=state.inventory[+e.code.slice(-1)-1];if(id){if(CLUE_ONLY.has(id))inspectItem(id);else{state.selected=state.selected===id?null:id;inventory();}}return;}if(['ArrowUp','ArrowDown','ArrowLeft','ArrowRight','Space'].includes(e.code))e.preventDefault();keys.add(e.code);if(e.code==='KeyE'&&active)interact(active.id);});document.addEventListener('keyup',e=>keys.delete(e.code));
canvas.addEventListener('pointerdown',e=>{if(!started||paused&&mode!=='inspect'||complete)return;drag=true;moved=false;canvas.setPointerCapture(e.pointerId);});canvas.addEventListener('pointermove',e=>{if(!drag||document.pointerLockElement)return;if(Math.abs(e.movementX)+Math.abs(e.movementY)>2)moved=true;if(mode==='inspect'&&inspectPivot){inspectPivot.rotation.y+=e.movementX*.009;inspectPivot.rotation.x+=e.movementY*.006;}else if(!paused){yaw-=e.movementX*.0025;pitch=Math.max(-1.3,Math.min(1.3,pitch-e.movementY*.0025));}});canvas.addEventListener('pointerup',()=>drag=false);canvas.addEventListener('click',e=>{if(!started||paused||complete||moved)return;pointer.set(e.clientX/innerWidth*2-1,-e.clientY/innerHeight*2+1);ray.setFromCamera(pointer,camera);const target=pickTarget();if(target){interact(target.id);return;}if(!document.pointerLockElement)canvas.requestPointerLock?.()?.catch?.(()=>{});});document.addEventListener('mousemove',e=>{if(document.pointerLockElement===canvas&&!paused&&!complete){yaw-=e.movementX*.0025;pitch=Math.max(-1.3,Math.min(1.3,pitch-e.movementY*.0025));}});canvas.addEventListener('wheel',e=>{if(mode==='inspect'){e.preventDefault();inspectDistance=Math.max(2.1,Math.min(5,inspectDistance+e.deltaY*.002));inspectCamera.position.z=inspectDistance;}},{passive:false});window.addEventListener('blur',()=>{keys.clear();drag=false;if(started&&!complete&&!paused)pause();});document.addEventListener('pointerlockchange',()=>keys.clear());
function pickTarget(){const hits=ray.intersectObjects(room.scene.children,true);for(const hit of hits){let o=hit.object;if(!o.visible||hit.distance>2.65)continue;let visible=true;for(let p=o.parent;p;p=p.parent)if(!p.visible)visible=false;if(!visible)continue;if(o.type==='Points'||o.type==='LineSegments'||o.material?.transparent&&o.material.opacity<.15)continue;let id=null,label='';while(o){if(o.userData.interactId){id=o.userData.interactId;label=o.userData.label;break;}o=o.parent;}if(id){if(id==='filmA'&&!crouched)return null;return{id,label,distance:hit.distance};}if(hit.object.isMesh)return null;}return null;}
function resize(){renderer.setSize(innerWidth,innerHeight);for(const c of[camera,inspectCamera]){c.aspect=innerWidth/innerHeight;c.updateProjectionMatrix();}}window.addEventListener('resize',resize);
function animate(){requestAnimationFrame(animate);const dt=Math.min(clock.getDelta(),.05);elapsed+=dt;room.update(dt,elapsed);
 if(mode==='inspect'){if(inspectionId==='frame')$('#inspectBackAction').hidden=!(Math.cos(inspectPivot.rotation.y)<-.6&&!state.inventory.includes('filmB')&&!state.filmJoined);renderer.render(inspectScene,inspectCamera);return;}
 if(!started){camera.position.set(.25,1.48,3.1);camera.rotation.set(-.015,-.3+Math.sin(elapsed*.07)*.025,0);}else if(!paused&&!complete){state.seconds+=dt;if(keys.has('ArrowLeft'))yaw+=dt*1.35;if(keys.has('ArrowRight'))yaw-=dt*1.35;if(keys.has('ArrowUp'))pitch=Math.min(1.3,pitch+dt);if(keys.has('ArrowDown'))pitch=Math.max(-1.3,pitch-dt);let mx=+keys.has('KeyD')-+keys.has('KeyA'),mz=+keys.has('KeyS')-+keys.has('KeyW');const len=Math.hypot(mx,mz)||1;mx/=len;mz/=len;const speed=(crouched?1.1:1.85)*dt,dx=(Math.cos(yaw)*mx+Math.sin(yaw)*mz)*speed,dz=(-Math.sin(yaw)*mx+Math.cos(yaw)*mz)*speed;if(room.canMove(player.x+dx,player.z))player.x+=dx;if(room.canMove(player.x,player.z+dz))player.z+=dz;player.y+=( (floorHeight(player.x,player.z)+(crouched?.56:1.62))-player.y)*Math.min(1,dt*9);camera.position.copy(player);if(mx||mz){camera.position.y+=Math.sin(elapsed*9)*.014;step+=dt;if(step>(crouched?.8:.55)){sound('wood');step=0;}}camera.rotation.set(pitch,yaw,0);const zone=zoneAt(player.x,player.z);if(zone==='hall'&&!state.suiteEscaped){state.suiteEscaped=true;state.selected=null;inventory();record('316호 밖의 호텔 복도','두 침실·거실·간이주방·욕실이 있던 316호를 나왔다. 복도 건너편에는 317호 객실이 있다.');caption('316호를 빠져나왔다. 여기는 호텔의 3층 복도다.\n건너편에 317호가 보인다.',6500);}if(zone==='room317'&&!state.room317Entered){state.room317Entered=true;state.selected=null;inventory();record('복도 건너편 317호에 들어서다','316호와 별개의 객실이다. 다른 투숙객의 물건이 그대로 남아 있다.');caption('317호. 다른 투숙객의 흔적이 남아 있다.',6500);}$('.room-title b').textContent=zone==='lowerHall'?'2F':zone==='hall'||zone==='stairs'?'3F':zone==='room317'||zone==='exitHall'?'317':'316';$('.room-title .overline').textContent=ZONES[zone]?.label||'316호 · 스위트룸';if(zone==='lowerHall'&&!state.lowerHallEntered){state.lowerHallEntered=true;record('2층 계단 로비','317호에서 계단문 열쇠를 찾아 복도로 돌아온 뒤, 고장 난 엘리베이터 대신 계단으로 내려왔다.');caption('2층에 도착했다. 계단을 통해 위층으로 돌아갈 수도 있다.',6500);}ray.setFromCamera(new T.Vector2(0,0),camera);active=pickTarget();$('#prompt').hidden=!active;if(active){$('#prompt span').textContent=active.label;$('#usePrompt').textContent=state.selected?'사용: '+ITEMS[state.selected]:'';}if(state.doorOpen&&!state.phoneHeard){phoneTimer+=dt;if(phoneTimer>6){sound('ring');phoneTimer=0;}}}
 eyeFill.position.copy(camera.position);eyeFill.intensity=started&&!state.lightOn?.8:0;renderer.render(room.scene,camera);}
animate();await room.ready;assetsReady=true;$('#loading').hidden=true;initializeAdmin();if(room.assetsFailed.length)toast('일부 재질을 불러오지 못했습니다. 기본 재질로 플레이할 수 있습니다.');

function openTeaLock(){
 if(state.kitchenOpen){caption('주방 문이 열려 있다.');return;}
 const names=['빈 잔','주전자','잎'],order=[2,2,2];
 modal('<h2>주방 문 · 서비스 순서</h2><p>세 문양을 서비스 순서대로 놓으면 문 잠금이 풀린다.</p><div class="ring-row">'+order.map((n,i)=>'<button data-tea="'+i+'">'+(i+1)+'번째: <span>'+names[n]+'</span></button>').join('')+'</div><button class="primary" id="teaSubmit">서비스 순서 확인</button><p id="teaFeedback" role="status"></p>');
 document.querySelectorAll('[data-tea]').forEach(b=>b.onclick=()=>{const i=+b.dataset.tea;order[i]=(order[i]+1)%3;b.querySelector('span').textContent=names[order[i]];sound('metal');});
 $('#teaSubmit').onclick=()=>{if(unlockKitchen(state,order)){closeModal();sound('unlock');record('주방 문','받침의 문양 뜻과 서비스 카드의 순서를 연결해 주방 문을 열었다.');caption('주방 문 안쪽의 걸쇠가 풀렸다.');}else $('#teaFeedback').textContent=!state.teaNoteSeen||!state.teaTraySeen?'서비스 카드와 찻잔 받침을 모두 조사해 문양의 뜻과 순서를 확인하자.':'서비스 조건과 맞지 않는다. 문양의 뜻과 앞뒤 관계를 다시 비교하자.';};
}
function openWaterStation(){
 if(!state.kitchenOpen){caption('주방 문을 먼저 열어야 한다.');return;}
 record('계량 보관함','3L 통과 5L 통. 가득 채우기·완전히 비우기·상대 통이 찰 때까지 옮기기만 가능하다. 큰 통이 정확히 4L면 열쇠 보관함이 열린다.');
 const actions=[['fillSmall','3L 통 채우기'],['emptySmall','3L 통 비우기'],['toLarge','3L → 5L 옮기기'],['fillLarge','5L 통 채우기'],['emptyLarge','5L 통 비우기'],['toSmall','5L → 3L 옮기기']];
 modal('<h2>주방 · 계량 보관함</h2><p>큰 통에 정확히 <strong>4L</strong>가 되면 부표가 걸쇠를 밀어 올린다. 보관함 안에는 TWIN 표식의 열쇠가 있다.</p><p class="muted">채우면 가득 차고, 비우면 모두 빠집니다. 옮기기는 한쪽이 비거나 다른 쪽이 찰 때까지 계속됩니다.</p><div id="waterLevels" aria-live="polite"></div><div class="water-controls">'+actions.map(([id,label])=>'<button class="outline" data-water="'+id+'">'+label+'</button>').join('')+'</div><p id="waterResult" role="status"></p>');
 const draw=()=>{$('#waterLevels').innerHTML='<div class="water-jugs">'+[[state.jugSmall,3],[state.jugLarge,5]].map(([v,max])=>'<div><svg viewBox="0 0 120 150" width="120" height="150" role="img" aria-label="'+max+'리터 통 현재 '+v+'리터"><path d="M20 10V130H100V10" fill="none" stroke="currentColor" stroke-width="4"/><rect x="23" y="'+(127-v/max*114)+'" width="74" height="'+v/max*114+'" fill="#689ba5"/>'+(max===5?'<path d="M10 36H110" stroke="#d8bb7a" stroke-dasharray="5 4"/><text x="102" y="30" fill="currentColor" font-size="12">4L</text>':'')+'</svg><p>'+v+' / '+max+' L</p></div>').join('')+'</div>';$('#waterResult').textContent=state.jugSolved?'딸깍. 보관함의 잠금이 풀렸다. 이 화면을 닫고 장치 왼쪽 상자 안에서 열쇠를 꺼내자.':'큰 통의 수면을 4L 표식에 맞추세요.';document.querySelectorAll('[data-water]').forEach(b=>b.disabled=state.jugSolved);};
 document.querySelectorAll('[data-water]').forEach(b=>b.onclick=()=>{const before=state.jugSolved;moveWater(state,b.dataset.water);draw();if(!before&&state.jugSolved){inventory();sound('unlock');record('계량 장치의 열쇠','큰 통에 정확히 4L가 남자 장치 왼쪽 열쇠 보관함이 열렸다.');}});draw();
}

function openTeaCup(){modal('<h2>찻잔과 받침</h2><p>받침 가장자리의 꽃무늬 옆으로 얇은 테이프 끝이 보인다.</p><button class="outline" id="flipCoaster">받침 뒤집기</button><div id="coasterBack"></div>');$('#flipCoaster').onclick=()=>{state.teaTraySeen=true;record('받침 뒷면의 문양','빈 잔 = 예열 / 주전자 = 물 붓기 / 잎 = 차 우리기. 꽃무늬 작은 열쇠가 테이프로 붙어 있었다.');$('#coasterBack').innerHTML='<div class="note">빈 잔 — 예열<br>주전자 — 물 붓기<br>잎 — 차 우리기</div>'+(!state.tinKeyTaken?'<button class="primary" id="takeTinKey">테이프를 떼고 작은 열쇠 꺼내기</button>':'<p>열쇠를 떼어낸 테이프 자국이 남아 있다.</p>');$('#flipCoaster').disabled=true;if($('#takeTinKey'))$('#takeTinKey').onclick=()=>{if(state.tinKeyTaken)return;state.tinKeyTaken=true;take('tinKey','꽃무늬 작은 열쇠','찻잔 받침 뒷면에서 찾았다. 미니바 차 상자에도 같은 꽃무늬가 있다.');closeModal();caption('작은 열쇠를 얻었다. I에서 손에 들어 차 상자에 사용할 수 있다.');};};}
